def solve_game(n):
    # State: (tuple_of_alice_choices, tuple_of_bob_choices, turn_of_alice)
    # Alice's choices and Bob's choices are sorted tuples.
    memo = {}

    def get_valid_moves(chosen_by_me, all_chosen, n):
        moves = []
        for i in range(1, n + 1):
            if i not in all_chosen:
                is_consecutive = False
                for choice in chosen_by_me:
                    if abs(choice - i) == 1:
                        is_consecutive = True
                        break
                if not is_consecutive:
                    moves.append(i)
        return moves

    def play(alice_choices, bob_choices, alice_turn):
        state = (tuple(sorted(alice_choices)), tuple(sorted(bob_choices)), alice_turn)
        if state in memo:
            return memo[state]

        all_chosen = set(alice_choices) | set(bob_choices)

        if len(all_chosen) == n:
            return 0 # Draw

        if alice_turn:
            moves = get_valid_moves(alice_choices, all_chosen, n)
            if not moves:
                return -1 # Alice loses, Bob wins

            # Alice wants to win (1), then draw (0), then lose (-1)
            best_res = -2
            for m in moves:
                res = play(alice_choices + (m,), bob_choices, False)
                if res == 1:
                    best_res = 1
                    break
                if res == 0:
                    best_res = max(best_res, 0)
                if res == -1:
                    best_res = max(best_res, -1)
            memo[state] = best_res
            return best_res
        else:
            moves = get_valid_moves(bob_choices, all_chosen, n)
            if not moves:
                return 1 # Bob loses, Alice wins

            # Bob wants to win (1), then draw (0), then lose (-1)
            # But the result is from Alice's perspective.
            # Let's redefine: 1 = Alice wins, 0 = Draw, -1 = Bob wins.
            best_res = 2
            for m in moves:
                res = play(alice_choices, bob_choices + (m,), True)
                # Bob wants to minimize the result (Alice's win status)
                if res == -1:
                    best_res = -1
                    break
                if res == 0:
                    best_res = min(best_res, 0)
                if res == 1:
                    best_res = min(best_res, 1)
            memo[state] = best_res
            return best_res

    # The return value is from Alice's perspective: 1 = Alice wins, 0 = Draw, -1 = Bob wins.
    return play((), (), True)

for n in range(1, 11):
    res = solve_game(n)
    print(f"n={n}, result={res}")

