def solve():
    def get_moves(player_nums, available):
        moves = []
        for x in available:
            if (x - 1) not in player_nums and (x + 1) not in player_nums:
                moves.append(x)
        return moves

    memo = {}

    def play(alice_nums, bob_nums, turn):
        state = (frozenset(alice_nums), frozenset(bob_nums), turn)
        if state in memo:
            return memo[state]

        alice_nums = set(alice_nums)
        bob_nums = set(bob_nums)
        available = [i for i in range(1, n + 1) if i not in alice_nums and i not in bob_nums]

        if not available:
            return 0 # Draw

        if turn == 0: # Alice's turn
            moves = get_moves(alice_nums, available)
            if not moves:
                return -1 # Alice loses

            results = []
            for m in moves:
                new_alice = alice_nums | {m}
                new_available = [x for x in available if x != m]
                if not new_available:
                    results.append(0) # Draw
                else:
                    results.append(play(new_alice, bob_nums, 1))

            if 1 in results:
                res = 1
            elif 0 in results:
                res = 0
            else:
                res = -1
        else: # Bob's turn
            moves = get_moves(bob_nums, available)
            if not moves:
                return -1 # Bob loses

            results = []
            for m in moves:
                new_bob = bob_nums | {m}
                new_available = [x for x in available if x != m]
                if not new_available:
                    results.append(0) # Draw
                else:
                    results.append(play(alice_nums, new_bob, 0))

            if 1 in results:
                res = 1
            elif 0 in results:
                res = 0
            else:
                res = -1

        memo[state] = res
        return res

    global n
    for i in range(1, 15):
        n = i
        memo = {}
        result = play(set(), set(), 0)
        print(f"n={i}, result={result}")

solve()

