def get_game_result(n):
    # A state is (tuple(sorted(alice_moves)), tuple(sorted(bob_moves)), turn)
    # turn 0: Alice, turn 1: Bob
    # Return 1 if Alice wins, -1 if Bob wins, 0 if Draw

    memo = {}

    def play(alice_moves, bob_moves, turn):
        state = (alice_moves, bob_moves, turn)
        if state in memo:
            return memo[state]

        alice_set = set(alice_moves)
        bob_set = set(bob_moves)
        all_chosen = len(alice_set) + len(bob_set) == n

        if all_chosen:
            return 0

        available = [i for i in range(1, n + 1) if i not in alice_set and i not in bob_set]

        if turn == 0:
            # Alice's turn
            possible_moves = []
            for m in available:
                if all(abs(m - prev) != 1 for prev in alice_moves):
                    possible_moves.append(m)

            if not possible_moves:
                res = -1 # Alice loses
            else:
                # Alice wants to maximize the result (1 > 0 > -1)
                res = -2
                for m in possible_moves:
                    new_alice_moves = tuple(sorted(alice_moves + (m,)))
                    val = play(new_alice_moves, bob_moves, 1)
                    if val > res:
                        res = val
                    if res == 1:
                        break
                # If no move leads to Alice winning (1), but some lead to a draw (0),
                # Alice will choose a draw.
                # Wait, the logic above already handles this: res = max(results of moves).
                # But we need to be careful if all moves lead to -1.
                if res == -2: # Should not happen as possible_moves is not empty
                    res = -1
            memo[state] = res
            return res
        else:
            # Bob's turn
            possible_moves = []
            for m in available:
                if all(abs(m - prev) != 1 for prev in bob_moves):
                    possible_moves.append(m)

            if not possible_moves:
                res = 1 # Bob loses
            else:
                # Bob wants to minimize the result (1 > 0 > -1)
                res = 2
                for m in possible_moves:
                    new_bob_moves = tuple(sorted(bob_moves + (m,)))
                    val = play(alice_moves, new_bob_moves, 0)
                    if val < res:
                        res = val
                    if res == -1:
                        break
                if res == 2: # Should not happen
                    res = 1
            memo[state] = res
            return res

    result = play((), (), 0)
    return result

