def solve():
    def get_moves(current_choices, n):
        moves = []
        for i in range(1, n + 1):
            if i not in current_choices:
                is_consecutive = False
                for choice in current_choices:
                    if abs(i - choice) == 1:
                        is_consecutive = True
                        break
                if not is_consecutive:
                    moves.append(i)
        return moves

    memo = {}

    def play(alice_choices, bob_choices, turn, n):
        state = (frozenset(alice_choices), frozenset(bob_choices), turn)
        if state in memo:
            return memo[state]

        # Check if all numbers are chosen
        if turn == n:
            return 0 # Draw

        # Whose turn is it?
        # Alice takes turns 0, 2, 4, ... (1st, 3rd, 5th, ...)
        # Bob takes turns 1, 3, 5, ... (2nd, 4th, 6th, ...)
        is_alice_turn = (turn % 2 == 0)

        current_choices = alice_choices if is_alice_turn else bob_choices
        moves = get_moves(current_choices, n)

        if not moves:
            # The player who cannot choose a number anymore loses.
            # If it's Alice's turn and she has no moves, Bob wins.
            # If it's Bob's turn and he has no moves, Alice wins.
            return -1 if is_alice_turn else 1

        # Possible results: 1 for Alice wins, -1 for Bob wins, 0 for draw.
        # Alice wants to maximize the result, Bob wants to minimize it.

        results = []
        for move in moves:
            if is_alice_turn:
                res = play(alice_choices | {move}, bob_choices, turn + 1, n)
            else:
                res = play(alice_choices, bob_choices | {move}, turn + 1, n)
            results.append(res)

        if is_alice_turn:
            # Alice wants to maximize
            best_res = max(results)
        else:
            # Bob wants to minimize
            best_res = min(results)

        memo[state] = best_res
        return best_res

    for n in range(1, 15):
        memo = {}
        result = play(set(), set(), 0, n)
        print(f"n={n}, result={result}")

solve()

