import sys
from functools import lru_cache

# Increase recursion depth for deep game trees
sys.setrecursionlimit(10000)

def solve():
    # We'll use a dictionary for memoization to be safe with memory and control.
    # Actually, lru_cache is also good.

    def get_result(n_val):
        @lru_cache(None)
        def play(alice_mask, bob_mask, turn):
            # alice_mask: bitmask of numbers chosen by Alice
            # bob_mask: bitmask of numbers chosen by Bob
            # turn: 0 for Alice, 1 for Bob

            # Current chosen numbers
            chosen_mask = alice_mask | bob_mask

            # Check if all numbers are chosen
            # All bits from 0 to n_val-1 should be set
            if chosen_mask == (1 << n_val) - 1:
                return 0

            # Find available moves
            moves = []
            if turn == 0: # Alice's turn
                for i in range(n_val):
                    # Number is i+1
                    if not ((chosen_mask >> i) & 1):
                        # Check if i+1 is consecutive to any of Alice's numbers
                        is_consecutive = False
                        for j in range(n_val):
                            if (alice_mask >> j) & 1:
                                if abs((j + 1) - (i + 1)) == 1:
                                    is_consecutive = True
                                    break
                        if not is_consecutive:
                            moves.append(i + 1)
            else: # Bob's turn
                for i in range(n_val):
                    if not ((chosen_mask >> i) & 1):
                        # Check if i+1 is consecutive to any of Bob's numbers
                        is_consecutive = False
                        for j in range(n_val):
                            if (bob_mask >> j) & 1:
                                if abs((j + 1) - (i + 1)) == 1:
                                    is_consecutive = True
                                    break
                        if not is_consecutive:
                            moves.append(i + 1)

            if not moves:
                return -1

            # Minimax logic:
            # If current player can move to a state where the next player loses (result -1),
            # then the current player wins (result 1).
            # Else if current player can move to a state that is a draw (result 0),
            # then the current player draws (result 0).
            # Otherwise, the current player loses (result -1).

            results = []
            for m in moves:
                if turn == 0:
                    results.append(play(alice_mask | (1 << (m - 1)), bob_mask, 1))
                else:
                    results.append(play(alice_mask, bob_mask | (1 << (m - 1)), 0))

            if -1 in results:
                return 1
            if 0 in results:
                return 0

