def solve_game(n):
    memo = {}

    def get_score(S_A, S_B, turn):
        # Use frozenset for memoization
        state = (frozenset(S_A), frozenset(S_B), turn)
        if state in memo:
            return memo[state]

        # Check if all numbers are chosen
        if len(S_A) + len(S_B) == n:
            return 0 # Draw

        current_S = S_A if turn == 0 else S_B
        possible_moves = []
        for i in range(1, n + 1):
            if i not in S_A and i not in S_B:
                is_consecutive = False
                for s in current_S:
                    if abs(i - s) == 1:
                        is_consecutive = True
                        break
                if not is_consecutive:
                    possible_moves.append(i)

        if not possible_moves:
            # Current player loses
            # If all numbers were chosen, it's a draw (already checked)
            # So the current player loses.
            return -1 if turn == 0 else 1

        results = []
        for move in possible_moves:
            if turn == 0:
                results.append(get_score(S_A | {move}, S_B, 1))
            else:
                results.append(get_score(S_A, S_B | {move}, 0))

        if turn == 0:
            res = max(results)
        else:
            res = min(results)

        memo[state] = res
        return res

    return get_score(set(), set(), 0)

