def solve_game(n):
    # memoization for minimax
    memo = {}

    def can_win(chosen_alice, chosen_bob, turn_alice):
        state = (tuple(sorted(chosen_alice)), tuple(sorted(chosen_bob)), turn_alice)
        if state in memo:
            return memo[state]

        # Possible moves
        moves = []
        all_chosen = set(chosen_alice) | set(chosen_bob)
        for i in range(1, n + 1):
            if i not in all_chosen:
                if turn_alice:
                    # Alice's turn
                    if all(abs(i - a) != 1 for a in chosen_alice):
                        moves.append(i)
                else:
                    # Bob's turn
                    if all(abs(i - b) != 1 for b in chosen_bob):
                        moves.append(i)

        if not moves:
            # Current player has no moves.
            # If all numbers are chosen, it's a draw.
            if len(all_chosen) == n:
                return 0  # Draw
            else:
                return -1  # Current player loses, so previous player wins

        # If any move leads to a state where the other player loses, this player wins.
        # A win is 1, a loss is -1, and a draw is 0.
        # Let's use 1 for win, -1 for loss, 0 for draw.
        # The player wants to win (1), then draw (0), then lose (-1).

        results = []
        for m in moves:
            if turn_alice:
                res = can_win(chosen_alice + (m,), chosen_bob, False)
            else:
                res = can_win(chosen_alice, chosen_bob + (m,), True)
            results.append(res)

        # If any move results in -1 (next player loses), this player wins.
        if -1 in results:
            memo[state] = 1
        elif 0 in results:
            memo[state] = 0
        else:
            memo[state] = -1

        return memo[state]

    # The game is a draw if the result is 0.
    # But wait, the minimax needs to be slightly different because players play to win,
    # and if they can't win, they play to draw.
    # My `can_win` already does this:
    # 1: Win
    # 0: Draw
    # -1: Loss
    # If any move leads to -1, return 1.
    # If no move leads to -1, but some lead to 0, return 0.
    # Otherwise, return -1.

    # Actually, the value returned by `can_win` is the result for the *current* player.
    # If it's 1, the current player wins.
    # If it's 0, it's a draw.
    # If it's -1, the current player loses.

    result = can_win((), (), True)
    return result

