def solve_game_v2(n):
    # Alice wants to win (1), then draw (0), then lose (-1).
    # Bob wants to win (1), then draw (0), then lose (-1).
    # Wait, the minimax value "1" means the current player will win.
    # "-1" means the current player will lose.
    # "0" means the current player will draw.

    memo = {}

    def minimax(chosen_alice, chosen_bob, turn_alice):
        # chosen_alice and chosen_bob are sorted tuples
        state = (chosen_alice, chosen_bob, turn_alice)
        if state in memo:
            return memo[state]

        all_chosen = set(chosen_alice) | set(chosen_bob)
        moves = []
        for i in range(1, n + 1):
            if i not in all_chosen:
                if turn_alice:
                    if all(abs(i - a) != 1 for a in chosen_alice):
                        moves.append(i)
                else:
                    if all(abs(i - b) != 1 for b in chosen_bob):
                        moves.append(i)

        if not moves:
            if len(all_chosen) == n:
                return 0
            else:
                return -1

        # The current player wants to maximize the result.
        # Results are from the perspective of the player whose turn it is.
        # If the result of a move is -1 (the *next* player loses), 
        # it means the *current* player wins (1).
        # If the result is 0 (draw), the *current* player draws (0).
        # If the result is 1 (the *next* player wins), the *current* player loses (-1).

        # Let's rethink this. 
        # Let f(state) be the outcome for the player whose turn it is.
        # f(state) = 1 if they can move to a state where the next player gets -1.
        # f(state) = 0 if they can't move to -1 but can move to a state where the next player gets 0.
        # f(state) = -1 if all moves lead to states where the next player gets 1.

        best_outcome = -2 # Worse than -1

        for m in moves:
            if turn_alice:
                res = minimax(tuple(sorted(chosen_alice + (m,))), chosen_bob, False)
            else:
                res = minimax(chosen_alice, tuple(sorted(chosen_bob + (m,))), True)

            # If the next player gets 'res', the current player's outcome is:
            # if res == -1: current player gets 1
            # if res == 0: current player gets 0
            # if res == 1: current player gets -1
            current_outcome = -1 if res == 1 else (0 if res == 0 else 1)

            if current_outcome > best_outcome:
                best_outcome = current_outcome

        memo[state] = best_outcome
        return best_outcome

    return minimax((), (), True)

